<?php require_once __DIR__.'/../functions.php';if(!admin())redirect('../login.php');if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$name=trim($_POST['name']);$desc=trim($_POST['description']);$price=(float)$_POST['price'];$img=trim($_POST['image']);$cap=max(1,(int)$_POST['capacity']);$status=$_POST['status'];if($id){$s=db()->prepare('UPDATE rooms SET name=?,description=?,price=?,image=?,capacity=?,status=? WHERE id=?');$s->execute([$name,$desc,$price,$img,$cap,$status,$id]);}else{$s=db()->prepare('INSERT INTO rooms(name,description,price,image,capacity,status) VALUES(?,?,?,?,?,?)');$s->execute([$name,$desc,$price,$img,$cap,$status]);}flash('Room saved.');redirect('rooms.php');}if(isset($_GET['delete'])){db()->prepare('DELETE FROM rooms WHERE id=?')->execute([(int)$_GET['delete']]);flash('Room deleted.');redirect('rooms.php');}$rows=db()->query('SELECT * FROM rooms ORDER BY id')->fetchAll();header_html('Manage Rooms');?><main class="container py-5"><div class="row g-4"><div class="col-lg-7"><h1>Rooms</h1><?php foreach($rows as $r):?><div class="card mb-3"><div class="card-body"><div class="d-flex justify-content-between"><div><h4><?=e($r['name'])?></h4><p><?=e($r['description'])?></p><b class="gold">TZS <?=number_format($r['price'])?></b> · capacity <?=$r['capacity']?> · <?=$r['status']?></div><a class="btn btn-sm btn-outline-danger h-100" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete this room?')">Delete</a></div><hr><form method="post" class="row g-2"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="col-md-6"><input name="name" class="form-control" value="<?=e($r['name'])?>" required></div><div class="col-md-3"><input name="price" type="number" class="form-control" value="<?=$r['price']?>" required></div><div class="col-md-3"><input name="capacity" type="number" class="form-control" value="<?=$r['capacity']?>" required></div><div class="col-12"><input name="image" class="form-control" value="<?=e($r['image'])?>"></div><div class="col-12"><textarea name="description" class="form-control"><?=e($r['description'])?></textarea></div><div class="col-md-4"><select name="status" class="form-select"><option <?=$r['status']=='active'?'selected':''?>>active</option><option <?=$r['status']=='inactive'?'selected':''?>>inactive</option></select></div><div class="col-md-8"><button class="btn btn-gold">Update room</button></div></form></div></div><?php endforeach;?></div><div class="col-lg-5"><div class="card"><div class="card-body"><h3>Add room</h3><form method="post"><input name="name" class="form-control mb-2" placeholder="Room name" required><input name="price" type="number" class="form-control mb-2" placeholder="Price per night" required><input name="capacity" type="number" class="form-control mb-2" value="2" required><input name="image" class="form-control mb-2" placeholder="Image URL"><textarea name="description" class="form-control mb-2" placeholder="Description"></textarea><input type="hidden" name="status" value="active"><button class="btn btn-gold w-100">Add room</button></form></div></div></div></div></main><?php footer_html();?>